function main({ data1, data2, data3 }) {
  let layoutData;
  try {
    layoutData = JSON.parse(data1);
  } catch (e) {
    throw new Error('data1 is not a valid JSON string');
  }

  const inputStartDate = data2;
  const days = parseInt(data3, 10);

  if (!Array.isArray(layoutData) || !inputStartDate || isNaN(days) || days <= 0) {
    throw new Error('Invalid input parameters');
  }

  // 构建排班映射，并收集所有存在的日期
  const scheduleMap = new Map();
  for (const item of layoutData) {
    if (item.shiftDate && item.shiftCode !== undefined) {
      scheduleMap.set(item.shiftDate, item.shiftCode);
    }
  }

  // 工具函数
  const parseDate = (str) => {
    const [y, m, d] = str.split('-').map(Number);
    return new Date(y, m - 1, d);
  };

  const formatDate = (date) => date.toISOString().split('T')[0];

  const addDays = (dateStr, numDays) => {
    const date = parseDate(dateStr);
    date.setDate(date.getDate() + numDays);
    return formatDate(date);
  };

  // 判断是否为休息日
  const isOffDay = (code) => {
    if (code == null) return false;
    const str = String(code).trim().toLowerCase();
    return str === 'off' || str === 'off_day' || str.startsWith('defaultoff');
  };

  // 🆕 新增逻辑：如果 inputStartDate 不在排班数据中
  if (!scheduleMap.has(inputStartDate)) {
    const startDate = inputStartDate;
    const endDate = addDays(inputStartDate, days - 1);
    return { startDate, endDate };
  }

  // 原有逻辑：inputStartDate 在排班范围内 → 按有效工作日计算

  if (days === 1) {
    return {
      startDate: inputStartDate,
      endDate: inputStartDate
    };
  }

  // 找第一个有效工作日
  let currentDate = parseDate(inputStartDate);
  let attempts = 0;
  const maxAttempts = 365 * 2;
  let actualStartDate = null;

  while (attempts < maxAttempts) {
    const dateStr = formatDate(currentDate);
    const shiftCode = scheduleMap.get(dateStr);

    if (shiftCode !== undefined && !isOffDay(shiftCode)) {
      actualStartDate = dateStr;
      break;
    }

    currentDate.setDate(currentDate.getDate() + 1);
    attempts++;
  }

  // 🆕 如果连第一个有效工作日都找不到，直接 fallback 到自然日
  if (!actualStartDate) {
    return {
      startDate: inputStartDate,
      endDate: addDays(inputStartDate, days - 1)
    };
  }

  // 从 actualStartDate 开始累计 days 个工作日
  currentDate = parseDate(actualStartDate);
  let count = 0;
  attempts = 0;

  while (count < days && attempts < maxAttempts) {
    const dateStr = formatDate(currentDate);
    const shiftCode = scheduleMap.get(dateStr);

    if (shiftCode !== undefined && !isOffDay(shiftCode)) {
      count++;
      if (count === days) {
        return {
          startDate: actualStartDate,
          endDate: dateStr
        };
      }
    }

    currentDate.setDate(currentDate.getDate() + 1);
    attempts++;
  }

  // 🆕 关键修改：如果累计不到 days 个工作日，fallback 到自然日
  // 从 original inputStartDate 开始算自然日（不是 actualStartDate！）
  return {
    startDate: inputStartDate,
    endDate: addDays(inputStartDate, days - 1)
  };
}

function main({ data1, data2, data3 }) {
  // 解析 data3：排班数据
  let shifts = [];
  try {
    shifts = JSON.parse(data3);
  } catch (e) {
    throw new Error("data3 格式错误，无法解析为 JSON 数组");
  }

  // 构建日期到排班信息的映射
  const shiftMap = new Map();
  for (const shift of shifts) {
    if (shift.shiftDate) {
      shiftMap.set(shift.shiftDate, shift);
    }
  }

  // 定义所有表示“休息日”的 shiftCode（精确匹配）
  const OFF_SHIFT_CODES = new Set([
    'OFF',
    'defaultOFF',
    'off_day',
    'DEFAULTOFF03'
    // 可根据实际业务继续添加
  ]);

  // 判断某天是否为休息日
  function isOffDay(dateStr) {
    const shift = shiftMap.get(dateStr);
    return shift && shift.shiftCode !== undefined && OFF_SHIFT_CODES.has(shift.shiftCode);
  }

  // 向后查找第一个非休息日（包含起始日）
  function findNextWorkday(startDateStr) {
    let currentDate = new Date(startDateStr);
    while (true) {
      const dateStr = currentDate.toISOString().split('T')[0];
      if (!isOffDay(dateStr)) {
        return dateStr;
      }
      currentDate.setDate(currentDate.getDate() + 1);
    }
  }

  // 向前查找第一个非休息日（包含结束日）
  function findPrevWorkday(endDateStr) {
    let currentDate = new Date(endDateStr);
    while (true) {
      const dateStr = currentDate.toISOString().split('T')[0];
      if (!isOffDay(dateStr)) {
        return dateStr;
      }
      currentDate.setDate(currentDate.getDate() - 1);
    }
  }

  // 调整 data1（开始日期）：向后找第一个工作日
  const adjustedData1 = findNextWorkday(data1);

  // 调整 data2（结束日期）：向前找第一个工作日
  const adjustedData2 = findPrevWorkday(data2);

  return {
    startDate: adjustedData1,
    endDate: adjustedData2
  };
}

function main({data1}){
    if (!data1) {
        return { result: "否" };
    }

    let days = null;

    // 处理“月”的情况
    if (typeof data1 === 'string' && data1.includes('月')) {
        const match = data1.match(/[\d.]+/);
        if (match) {
            const months = parseFloat(match[0]);
            if (!isNaN(months)) {
                days = months * 30;
            }
        }
    }
    // 处理“天”的情况（也包括纯数字+天，如 "1.5天"）
    else if (typeof data1 === 'string' && (data1.includes('天') || /^\s*[\d.]+\s*$/.test(data1))) {
        const match = data1.match(/[\d.]+/);
        if (match) {
            const num = parseFloat(match[0]);
            if (!isNaN(num)) {
                days = num;
            }
        }
    }

    // 无法解析有效天数
    if (days === null || isNaN(days)) {
        return { result: "否" };
    }

    // 判断是否大于27天
    if (days > 27) {
        return { result: "否" };
    }

    // 向上取整并返回字符串
    return { result: String(Math.ceil(days)) };
}

function main({ data1, data2, data3 }) {
  const startDateStr = data2; // e.g. "2025-11-14"
  const days = parseInt(data3, 10);

  // 校验输入
  if (!startDateStr || isNaN(days) || days <= 0) {
    throw new Error('Invalid input: startDate or days is missing or invalid');
  }

  // 解析起始日期（确保是合法日期字符串）
  const startDate = new Date(startDateStr);
  if (isNaN(startDate.getTime())) {
    throw new Error('Invalid startDate format. Expected YYYY-MM-DD');
  }

  // 计算结束日期：从 startDate 开始，经过 (days - 1) 天
  const endDate = new Date(startDate);
  endDate.setDate(startDate.getDate() + days - 1);

  const endDateStr = endDate.toISOString().split('T')[0];

  return {
    startDate: startDateStr,
    endDate: endDateStr
  };
}
